tape( 'the function throws an error if provided a separators ndarray which is not broadcast-compatible', function test( t ) {
	var values;
	var opts;
	var x;
	var y;
	var i;

	opts = {
		'dtype': 'generic'
	};
	x = zeros( [ 2, 2 ], opts );
	y = empty( [ 2 ], opts );

	values = [
		zeros( [ 4 ], opts ),
		zeros( [ 2, 2, 2 ], opts ),
		zeros( [ 0 ], opts )
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), Error, 'throws an error when provided incompatible separators' );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			joinBetween( x, value, y );
		};
	}
});

