tape( 'the function supports per-pair separators', function test( t ) {
	var expected;
	var actual;
	var seps;
	var xbuf;
	var out;
	var x;

	xbuf = [ 1.0, 2.0, 3.0, 4.0 ];
	x = new ndarray( 'generic', xbuf, [ 4 ], [ 1 ], 0, 'row-major' );
	out = empty( [], {
		'dtype': 'generic'
	});

	seps = new ndarray( 'generic', [ ' + ', ' - ', ' != ' ], [ 3 ], [ 1 ], 0, 'row-major' );

	actual = joinBetween( x, seps, out, {
		'prefix': 'op: ',
		'suffix': ''
	});
	expected = 'op: 1 + 2 - 3 != 4';

	t.strictEqual( isndarrayLike( actual ), true, 'returns expected value' );
	t.deepEqual( actual.get(), expected, 'returns expected value' );
	t.strictEqual( actual, out, 'returns expected value' );

	t.end();
});

